package com.autoops.credential.service;import com.autoops.credential.entity.Credential;import com.autoops.credential.repository.CredentialRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;@Service public class CredentialManagementService{private final CredentialRepository repo;private final CredentialCryptoService crypto;public CredentialManagementService(CredentialRepository r,CredentialCryptoService c){repo=r;crypto=c;}public record View(Long id,String name,String username){}public List<View> list(Long user){return repo.findAll().stream().filter(c->user.equals(c.getCreatedBy())).map(this::view).toList();}@Transactional public View create(Long user,String name,String username,String password){if(name==null||name.isBlank()||username==null||username.isBlank()||password==null||password.isBlank())throw new IllegalArgumentException("Name, username and password are required");var encrypted=crypto.encrypt(password);var c=new Credential();c.setName(name.trim());c.setUsername(username.trim());c.setEncryptedPassword(encrypted.ciphertext());c.setEncryptionIv(encrypted.iv());c.setCreatedBy(user);return view(repo.save(c));}@Transactional public void delete(Long user,Long id){var c=repo.findById(id).orElseThrow();if(!user.equals(c.getCreatedBy()))throw new SecurityException("Credential not owned by current user");repo.delete(c);}private View view(Credential c){return new View(c.getId(),c.getName(),c.getUsername());}}
